import {harvestCrop} from './crops.js?v=garden131';
// Pure local-alpha rules. No real currency, shared users or payment claims.
export const GOODS={seeds:'Maize seeds',water:'Water',maize:'Maize',feed:'Grain feed',fruit:'Fruit feed',power:'Power',eggs:'Eggs',specialEggs:'Specialty eggs',milk:'Milk',fertiliser:'Fertiliser',truffles:'Truffles',condition:'Condition points'};
export const RATIONS={cow:{feed:4,water:6,fruit:1},pig:{feed:3,water:4,fruit:1},chicken:{feed:1,water:1,fruit:0},horse:{feed:5,water:6,fruit:2}};
export const HERDS=[{id:'cows',name:'Dairy paddock',type:'cow',count:2,goods:{milk:8,fertiliser:2}},{id:'pigs',name:'Pig paddock',type:'pig',count:2,goods:{truffles:2,fertiliser:4}},{id:'hens',name:'Chicken yard',type:'chicken',count:3,goods:{eggs:4,specialEggs:2}},{id:'horses',name:'Horse paddock',type:'horse',count:2,goods:{condition:2,fertiliser:2}}];
export const OFFERS=[{good:'seeds',seller:'Sunfield Seed House',price:3,stock:160,buy:60},{good:'water',seller:'Willow Wells',price:1,stock:240,buy:100},{good:'maize',seller:'Sunfield Crops',price:2,stock:180,buy:90},{good:'feed',seller:'Oak Mill',price:4,stock:140,buy:80},{good:'fruit',seller:'Orchard Lane',price:3,stock:90,buy:50},{good:'power',seller:'Breeze Energy',price:2,stock:90,buy:50},{good:'eggs',seller:'Maple Bakery',price:3,stock:0,buy:40},{good:'specialEggs',seller:'Village Kitchen',price:5,stock:0,buy:20},{good:'milk',seller:'Meadow Dairy',price:4,stock:0,buy:70},{good:'fertiliser',seller:'Green Gardens',price:2,stock:0,buy:60},{good:'truffles',seller:'Village Kitchen',price:8,stock:0,buy:20}];
export function fresh(role='livestock'){return {version:2,role,coins:800,day:1,avatar:'man',crop:null,inventory:{seeds:8,water:20,maize:12,feed:24,fruit:6,power:4,eggs:0,specialEggs:0,milk:0,fertiliser:0,truffles:0,condition:0},troughs:Object.fromEntries(HERDS.map(h=>[h.id,{feed:0,water:0,fruit:0}])),wellReady:0,cropReady:0,offers:OFFERS.map(o=>({...o})),history:[],delivered:0};}
export function herdCount(h,s){return h.type==='horse'&&Array.isArray(s?.horses)?s.horses.length:h.count;}
export function demand(h,s){let r=RATIONS[h.type];return Object.fromEntries(Object.entries(r).map(([k,v])=>[k,v*herdCount(h,s)]));}
export function fill(s,id,kind){let h=HERDS.find(h=>h.id===id);if(!h||!['feed','water','fruit'].includes(kind))throw Error('Unknown trough');let required=demand(h,s)[kind],amount=Math.max(0,required-s.troughs[id][kind]);if(!amount)throw Error('This ration is already full');if(s.inventory[kind]<amount)throw Error(`Need ${amount} ${GOODS[kind]}; buy supplies at the market`);s.inventory[kind]-=amount;s.troughs[id][kind]+=amount;return amount;}
export function collectWell(s){if(s.role!=='water')throw Error('Your farm does not own a well. Buy water from a supplier.');if(s.wellReady>s.day)throw Error('Well refills next farm day');if(s.inventory.power<1)throw Error('Pumping needs 1 power');s.inventory.power--;s.inventory.water+=40;s.wellReady=s.day+1;return 40;}
export const harvest=harvestCrop;
export function mill(s){if(s.role!=='miller')throw Error('Your farm does not own a mill. Buy grain feed from a miller.');if(s.inventory.maize<10||s.inventory.power<1)throw Error('One batch needs 10 maize + 1 power');s.inventory.maize-=10;s.inventory.power--;s.inventory.feed+=10;return 10;}
export function advance(s){let produced=[],skipped=[];if(s.role==='livestock')for(const h of HERDS){let need=demand(h,s),t=s.troughs[h.id];if(Object.entries(need).every(([k,v])=>t[k]>=v)){for(const [k,v] of Object.entries(need))t[k]-=v;for(const [k,v] of Object.entries(h.goods))s.inventory[k]+=v;produced.push(h.name);}else skipped.push(h.name);}s.day++;return {produced,skipped};}
export function trade(s,good,quantity,side){if(!Number.isInteger(quantity)||quantity<=0||quantity>1000)throw Error('Choose a whole quantity from 1 to 1000');let o=s.offers.find(o=>o.good===good);if(!o||!['buy','sell'].includes(side))throw Error('Unknown offer');let gross=o.price*quantity,fee=side==='sell'?Math.ceil(gross*.05):0;if(side==='buy'){if(o.stock<quantity)throw Error('Supplier has insufficient remaining stock');if(s.coins<gross)throw Error('Insufficient farm coins');s.coins-=gross;s.inventory[good]+=quantity;o.stock-=quantity;}else{if(s.inventory[good]<quantity)throw Error('Not enough goods in storage');if(o.buy<quantity)throw Error('Demo buyer has insufficient remaining demand');s.inventory[good]-=quantity;s.coins+=gross-fee;o.buy-=quantity;}s.history.unshift({day:s.day,side,good,quantity,gross,fee});s.history=s.history.slice(0,30);return {gross,fee};}
